import React from 'react';
import './sidebar.css';
type Page = 'overview' | 'projects' | 'members' | 'billing';
export function Sidebar({selected, onNavigate, onHelp, onSettings}: {selected: Page; onNavigate: (page: Page) => void; onHelp: () => void; onSettings: () => void}) {
 const sections: {label: string; rows: {id: Page; label: string; icon?: string; disabled?: boolean}[]}[] = [{label:'Workspace', rows:[{id:'overview',label:'Overview',icon:'◫'},{id:'projects',label:'Projects'}]},{label:'Organization',rows:[{id:'members',label:'Members',icon:'♧'},{id:'billing',label:'Billing',disabled:true}]}];
 return <aside className="sidebar"><nav aria-label="Primary">{sections.map(section => <section key={section.label} aria-label={section.label}><h2>{section.label}</h2><ul>{section.rows.map(row => <li key={row.id}><button className="nav-row" disabled={row.disabled} aria-current={selected === row.id ? 'page' : undefined} onClick={() => onNavigate(row.id)}><span className="nav-icon" aria-hidden="true">{row.icon}</span><span>{row.label}{row.disabled && <small>Unavailable</small>}</span></button></li>)}</ul></section>)}</nav><section className="workspace-summary" aria-label="Workspace summary"><strong>Design workspace</strong><p>12 members · 4 projects</p></section><footer><button onClick={onHelp}>Help</button><button onClick={onSettings}>Settings</button></footer></aside>;
}
